  result.d_hhat[3][3] = ref_gauge_cse_134*(-ref_gauge_cse_133 - ref_gauge_cse_158 - ref_gauge_cse_161 - ref_gauge_cse_163 - ref_gauge_cse_168 - ref_gauge_cse_8*ref_gauge_cse_89 - ref_gauge_cse_8*ref_gauge_cse_90);
