    case 59: return L*(-L_tr*X1/(Kokkos::pow(L, 2)*radius) + 2*L_r*L_t*X1/(Kokkos::pow(L, 3)*radius)) - L_r*L_t*X1/(Kokkos::pow(L, 2)*radius);
